import pytest
from isort import sections
from isort.deprecated.finders import ReqsBaseFinder
from isort.settings import Config
from collections.abc import Iterator

class MockReqsBaseFinder(ReqsBaseFinder):
    def __init__(self, config: Config, path: str = '.') -> None:
        super().__init__(config, path)
        self.names = ['numpy', 'pandas']

    def _get_files_from_dir(self, path: str) -> Iterator[str]:
        return iter([])  # Mock implementation

    def _get_names(self, path: str) -> Iterator[str]:
        return iter(self.names)  # Return the names set in the instance

@pytest.fixture
def config():
    return Config()  # Provide a mock or default config

class TestReqsBaseFinder:
    @pytest.fixture
    def finder(self, config):
        finder = MockReqsBaseFinder(config)
        finder.enabled = True
        return finder

    def test_find_enabled_with_matching_name(self, finder):
        result = finder.find('numpy')
        assert result == sections.THIRDPARTY

    def test_find_enabled_with_non_matching_name(self, finder):
        result = finder.find('scipy')
        assert result is None

    def test_find_enabled_with_empty_name(self, finder):
        result = finder.find('')
        assert result is None

    def test_find_disabled(self, finder):
        finder.enabled = False
        result = finder.find('numpy')
        assert result is None

    def test_find_with_submodules(self, finder):
        result = finder.find('numpy.submodule')
        assert result == sections.THIRDPARTY  # Assuming submodules should return the same section

    def test_find_with_lowercase_name(self, finder):
        result = finder.find('PANDAS')
        assert result == sections.THIRDPARTY  # Check case insensitivity
